import {COURSES,SUBJECT_GROUPS,courseById} from './catalog.mjs';
import {buildTypeCatalog,officialTypeAnalysis,learningTypeAnalysis,ANALYSIS_COURSES,analysisCourseById,analysisLearningCourseId} from './analysis.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=(rows,value)=>rows.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('');
const btn=(label,action,attrs='',cls='')=>`<button class="btn small ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const pct=n=>n===null?'—':n.toFixed(1)+'%';
const tile=(title,value,caption)=>`<div class="card analysis-tile"><span>${title}</span><strong>${value}</strong><p>${caption}</p></div>`;
function scopeDescription(data,a,course){
 const n=id=>a.counts[id]||0;
 if(course?.id==='english')return `영어는 2018~2027학년도에 걸쳐 ${n('english')}문항을 홀수형 한 회씩 분류했습니다.`;
 if(course?.domain==='국어'){
  if(!data.koreanScope)return data._koreanLoadError?'국어 유형 자료를 불러오지 못했습니다. 새로고침 후 다시 확인해 주세요.':'이 과목의 공식 기출 문항 유형 분류는 아직 추가 중입니다.';
  if(course.legacy)return `2018~2021학년도 국어 전체 1~45번, 총 ${n(course.id)}문항입니다. 당시 단일 시험을 현행 공통·선택과목과 구분하여 집계합니다.`;
  return course.id==='korean-common'?`2022~2027학년도 공통 1~34번, 총 ${n(course.id)}문항입니다. 독서·문학을 포함하며 선택과목마다 같은 공통 문항을 반복 집계하지 않습니다.`:`2022~2027학년도 ${course.label} 35~45번, 총 ${n(course.id)}문항입니다. 공통 34문항은 이 선택과목의 분모에 포함하지 않습니다.`;
 }
 if(course?.domain==='수학'){
  if(!data.mathScope)return course.id==='math-common'?'수학 공통은 2022~2026학년도 1·2번, 총 10문항 표본입니다. 기초 문항에 한정된 구성입니다.':'이 과목의 수학 유형 자료를 불러오지 못했습니다. 수학 전체 분석으로 다시 확인해 주세요.';
  if(course.legacy)return `${course.label}의 각 30문항, 총 ${n(course.id)}문항을 해당 시험지 기준으로 분류했습니다. 현행 공통·선택과목과 별도로 집계합니다.`;
  return course.id==='math-common'?`2022~2027학년도 공통 1~22번, 총 ${n(course.id)}문항입니다. 선택과목마다 같은 공통 문항을 반복 집계하지 않습니다.`:`2022~2027학년도 ${course.label} 23~30번, 총 ${n(course.id)}문항입니다. 공통 22문항은 이 선택과목의 분모에 포함하지 않습니다.`;
 }
 if(course)return '이 과목의 공식 기출 문항 유형 분류는 아직 추가 중입니다. 내 학습 분석에서는 자체 연습과 유형 변형의 채점 기록을 볼 수 있습니다.';
 const math=a.all.filter(r=>r.domain==='수학').length,korean=a.all.filter(r=>r.domain==='국어').length;
 return `현재 분류 자료는 국어 ${korean}문항, 영어 ${n('english')}문항, 수학 ${math}문항입니다. 과목·시험 체계에 따라 분류 범위를 나누어 비교해 주세요.`;
}
export function analysisView({data,pasts,authored,db,ui}){
 const filters={domain:ui.analysisDomain,courseId:ui.analysisCourse,year:ui.analysisYear,unit:ui.analysisUnit,typeId:ui.analysisType},catalog=buildTypeCatalog(data),official=officialTypeAnalysis(data,pasts,filters),learning=ui.analysisMode==='learning',own=learning?learningTypeAnalysis(db,pasts,authored,{...filters,year:''},data):null;
 const course=analysisCourseById(filters.courseId),courses=ANALYSIS_COURSES.filter(c=>!filters.domain||c.domain===filters.domain),allTypes=[...catalog.values()].filter(t=>(!filters.domain||analysisCourseById(t.courseId)?.domain===filters.domain)&&(!filters.courseId||t.courseId===filters.courseId)),units=[...new Set(allTypes.map(t=>t.unit))].sort((a,b)=>a.localeCompare(b,'ko'));
 const courseLabel=course?.label||filters.domain||'전체 과목',sourceTypes=learning?allTypes:allTypes.filter(t=>official.all.some(r=>r.typeId===t.id)),types=sourceTypes.filter(t=>!filters.unit||t.unit===filters.unit);
 const head=`<div class="page-heading"><div><div class="eyebrow">TYPE ANALYSIS</div><h1>유형 분석</h1><p>기출의 구성과 내 풀이 기록을 과목·단원·유형으로 살펴보세요.</p></div></div><div class="tabs">${[['official','기출 유형 분석'],['learning','내 학습 유형 분석']].map(([mode,label])=>`<button class="tab ${ui.analysisMode===mode?'active':''}" data-action="analysis-mode" data-mode="${mode}">${label}</button>`).join('')}</div><div class="analysis-filters"><label>영역<select data-filter="analysisDomain" aria-label="분석 영역">${opt([['','전체 영역'],...SUBJECT_GROUPS.map(g=>[g.id,g.id])],filters.domain)}</select></label><label>과목<select data-filter="analysisCourse" aria-label="분석 과목">${opt([['','전체 과목'],...courses.map(c=>[c.id,c.label])],filters.courseId)}</select></label>${!learning?`<label>학년도<select data-filter="analysisYear" aria-label="분석 학년도">${opt([['','전체 분류 학년도'],...official.years.map(y=>[y,y+'학년도'])],filters.year)}</select></label>`:''}<label>학습 단원<select data-filter="analysisUnit" aria-label="분석 단원">${opt([['','전체 단원'],...units.map(u=>[u,u])],filters.unit)}</select></label><label>문제 유형<select data-filter="analysisType" aria-label="분석 문제 유형">${opt([['','전체 유형'],...types.map(t=>[t.id,t.label])],filters.typeId)}</select></label></div>`;
 let body;
 if(learning){
  const a=own;
  body=`<div class="analysis-summary">${tile('풀이한 문항',`${a.total}<small>문항</small>`,'동일한 원문 문제는 최신 채점 1회로 집계')}${tile('정답률',pct(a.accuracy),`${a.correct}문항 정답 · ${a.wrong}문항 오답`)}${tile('아직 복습할 오답',`${a.unresolved}<small>문항</small>`,'직접 복습 완료로 표시한 문항은 제외')}</div><div class="notice"><div><strong>${esc(courseLabel)} · 이 기기의 채점 기록 기준</strong><p>해설을 먼저 본 풀이를 제외합니다. 동일한 자체 개념 문제를 다시 푼 기록도 한 문제로 묶습니다. 3문항 미만 유형은 비율 대신 오답 횟수를 표시합니다.</p></div></div>${a.frequencies.length?`<section class="card analysis-card"><div class="section-heading"><div><h2>유형별 학습 상태</h2><p>남은 오답이 많은 유형부터 표시합니다.</p></div></div><div class="analysis-table-scroll"><table class="analysis-table"><thead><tr><th>유형·단원</th><th>풀이</th><th>오답</th><th>오답률</th><th>남은 오답</th><th>다시 학습</th></tr></thead><tbody>${a.frequencies.map(g=>{const wrong=a.rows.find(r=>r.typeId===g.id&&!r.correct),qid=wrong?.qid||g.qids.at(-1);return `<tr><th>${esc(g.label)}<small>${esc(g.unit)}</small></th><td>${g.count}문항</td><td>${g.wrong}문항</td><td>${g.smallSample?`${g.wrong}/${g.count}<small>초기 기록</small>`:pct(g.wrongRate)}</td><td>${g.unresolved}문항</td><td><div class="analysis-actions">${btn(wrong?'틀린 문제 보기':'최근 문제 보기','open-question',`data-id="${esc(qid)}"`)}${g.practiceTopicId?btn('같은 유형 연습','topic-practice',`data-topic="${esc(g.practiceTopicId)}"`):''}</div></td></tr>`}).join('')}</tbody></table></div></section>`:`<div class="empty"><h3>아직 이 범위의 채점 기록이 없습니다.</h3><p>문제를 직접 풀고 채점하면 유형별 오답과 복습할 문제를 확인할 수 있습니다.</p>${btn('과목 연습으로','course-practice',`data-course="${esc(analysisLearningCourseId(course?.id))}"`,'primary')}</div>`}`;
 }else{
  const a=official,selectedType=catalog.get(filters.typeId),coverage=scopeDescription(data,a,course),mathCount=a.all.filter(r=>r.domain==='수학').length,koreanCount=a.all.filter(r=>r.domain==='국어').length,multipleCourses=new Set(a.rows.map(r=>r.courseId)).size>1,groupLabel=g=>esc(g.label)+(multipleCourses?`<small>${esc(analysisCourseById(g.courseId)?.label)}</small>`:'');
  body=`<div class="analysis-summary">${tile('선택 범위의 기출 분류',`${a.total}<small>문항</small>`,`${esc(courseLabel)} · ${a.yearCount}개 학년도`)}${tile('문제 유형',`${a.frequencies.length}<small>개</small>`,'발문·지문·조건의 대표 평가 내용 기준')}${tile('전체 분류 데이터',`${a.all.length}<small>문항</small>`,`국어 ${koreanCount}문항 + 영어 ${a.counts.english||0}문항 + 수학 ${data.mathScope?'':'표본 '}${mathCount}문항`)}</div><div class="notice"><div><strong>분석에 사용한 문항 범위</strong><p>${esc(coverage)} 유형은 학습을 위해 구성한 분류입니다.</p></div></div>${data?._loadError?'<div class="notice amber">유형 자료를 불러오지 못했습니다. 새로고침 후 다시 확인해 주세요.</div>':''}`;
  if(data?._mathLoadError&&(!filters.domain||filters.domain==='수학'))body+='<div class="notice amber">수학 유형 자료를 불러오지 못했습니다. 새로고침 후 다시 확인해 주세요. 현재 수학은 기존 10문항 표본만 표시합니다.</div>';
  if(data?._koreanLoadError&&(!filters.domain||filters.domain==='국어'))body+='<div class="notice amber">국어 유형 자료를 불러오지 못했습니다. 새로고침 후 다시 확인해 주세요. 현재 국어의 공식 기출 유형 통계는 표시하지 않습니다.</div>';
  if(data.koreanScope&&(!filters.domain||filters.domain==='국어'))body+='<div class="notice"><div><strong>국어 집계 기준</strong><p>2018~2021 단일 시험 45문항과 2022~2027 공통 34문항·선택과목별 11문항을 구분합니다. 현행 공통 문항은 한 번만 집계합니다. 두 선택과목을 합한 56문항은 한 수험생의 시험 문항 수가 아닙니다. 발문·지문 묶음·선택지를 대조해 복합 문항에 대표 유형 하나를 부여합니다.</p></div></div>';
  if(data.mathScope&&(!filters.domain||filters.domain==='수학'))body+='<div class="notice"><div><strong>수학 집계 기준</strong><p>2018~2021 가·나형과 2022~2027 공통·선택과목을 나누어 봅니다. 가·나형에 같은 내용이 실렸으면 각 형에서 한 번씩 집계하고, 현행 공통 22문항은 선택과목마다 중복하지 않습니다. 여러 형·선택과목의 합계는 한 수험생의 시험 문항 수가 아닙니다. 복합 문항은 대표 개념 하나로 분류합니다.</p></div></div>';
  if(a.total){
   body+=`<div class="analysis-columns"><section class="card analysis-card"><div class="section-heading"><div><h2>유형별 문항 구성</h2><p>분류한 ${a.total}문항 내 비중 · 소수점 첫째 자리 반올림</p></div>${filters.typeId?btn('전체 유형','analysis-clear-type'):''}</div><div class="analysis-bars">${a.frequencies.map(g=>`<button class="analysis-bar ${filters.typeId===g.id?'selected':''}" data-action="analysis-type" data-type="${esc(g.id)}" aria-pressed="${filters.typeId===g.id}"><span class="analysis-bar-top"><strong>${groupLabel(g)}</strong><span>${g.count}문항 · ${pct(g.share)}</span></span><span class="analysis-bar-track"><span style="width:${Math.max(0,Math.min(100,g.share)).toFixed(2)}%"></span></span></button>`).join('')}</div></section><aside class="card analysis-card analysis-reading"><span class="eyebrow">READ THE PATTERN</span><h2>${selectedType?esc(selectedType.label):'비율보다 먼저, 분모를 확인하세요.'}</h2><p>${selectedType?esc(selectedType.method):'현재 선택한 과목·학년도·단원에서 분류한 문항 수가 분모입니다. 원문 PDF 수와 문항 수를 구분해 집계합니다.'}</p><div class="analysis-definition"><strong>출제 비중</strong><p>해당 유형 문항 수 ÷ 선택 범위의 분류 문항 수 × 100</p></div><p>과거 집계 비율은 다음 시험의 출제 확률을 의미하지 않습니다. ${data.mathScope?'과목·시험 체계가 다른 전체 합계를 한 수험생의 출제 비중으로 해석할 수 없습니다.':'수학 표본을 전체 수학의 출제 분포로 일반화할 수 없습니다.'}</p>${selectedType?.practiceTopicId?btn('연결된 기초 유형 연습','topic-practice',`data-topic="${esc(selectedType.practiceTopicId)}"`,'primary'):btn('공식 시험지 보기','course-archive',`data-course="${esc(analysisLearningCourseId(course?.id))}"`)}</aside></div>`;
   const matrixYears=filters.year?a.years.filter(y=>y===Number(filters.year)):a.years;
   body+=`<section class="card analysis-card"><div class="section-heading"><div><h2>학년도별 유형 비교</h2><p>숫자는 분류된 문항 수입니다. —는 해당 학년도에 집계한 문항이 없다는 뜻입니다.</p></div></div><div class="analysis-table-scroll"><table class="analysis-table analysis-matrix"><thead><tr><th>문제 유형</th>${matrixYears.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${a.frequencies.map(g=>`<tr><th>${groupLabel(g)}</th>${matrixYears.map(y=>{const n=g.years[y]||0,total=a.yearTotals[y];return `<td title="${y}학년도 분류 ${total}문항 중 ${n}문항" class="${n?'has-count':''}">${total?n:'—'}</td>`}).join('')}</tr>`).join('')}</tbody><tfoot><tr><th>집계한 전체 문항</th>${matrixYears.map(y=>`<td>${a.yearTotals[y]||'—'}</td>`).join('')}</tr></tfoot></table></div></section>`;
   const pages=Math.max(1,Math.ceil(a.detail.length/20)),page=Math.max(1,Math.min(ui.analysisPage||1,pages));
   body+=`<section class="card analysis-card"><div class="section-heading"><div><h2>${selectedType?esc(selectedType.label)+' · ':''}분류 근거 문항</h2><p>${a.detail.length}문항 · 원문에서 문항 번호와 위치를 확인할 수 있습니다.</p></div></div><div class="analysis-table-scroll"><table class="analysis-table"><thead><tr><th>학년도·문항</th><th>단원·유형</th><th>풀이 접근</th><th>원문 확인</th></tr></thead><tbody>${a.detail.slice((page-1)*20,page*20).map(r=>{const m=catalog.get(r.typeId);return `<tr><th>${r.year}학년도 ${r.questionNumber}번<small>${esc(analysisCourseById(r.courseId)?.label)}${r.points?` · ${r.points}점`:""}</small></th><td>${esc(m?.label)}<small>${esc(r.unit)}</small></td><td>${esc(m?.method)}</td><td>${r.questionId?btn('문제·해설 보기','open-question',`data-id="${esc(r.questionId)}"`):btn('시험지에서 보기','analysis-paper',`data-id="${esc(r.id)}"`)}</td></tr>`}).join('')||'<tr><td colspan="4">선택한 학년도·단원에 이 유형의 문항이 없습니다.</td></tr>'}</tbody></table></div>${pages>1?`<div class="pagination">${btn('이전','analysis-page',`data-page="${page-1}" ${page===1?'disabled':''}`)}<span>${page} / ${pages}</span>${btn('다음','analysis-page',`data-page="${page+1}" ${page===pages?'disabled':''}`)}</div>`:''}</section>`;
  }else body+=`<div class="empty"><h3>이 범위에 분류된 공식 기출 문항이 없습니다.</h3><p>과목·학년도 필터를 바꾸거나 내 학습 유형 분석을 이용해 보세요.</p>${btn('내 학습 분석','analysis-mode','data-mode="learning"','primary')}</div>`;
  body+=`<details class="card analysis-card analysis-coverage"><summary>과목별 기출 분류 현황 · ${COURSES.length}개 학습 항목·과거 국어·수학 3개 범위</summary><div class="analysis-table-scroll"><table class="analysis-table"><thead><tr><th>영역</th><th>과목</th><th>분류 문항</th><th>범위</th></tr></thead><tbody>${ANALYSIS_COURSES.map(c=>`<tr><td>${c.domain}</td><th>${c.label}</th><td>${a.counts[c.id]||0}문항</td><td>${esc(scopeDescription(data,a,c))}</td></tr>`).join('')}</tbody></table></div></details>`;
 }
 return head+body+'<p class="footnote">원문 PDF 열람, 문항별 유형 분류, 내 채점 기록은 각각의 실제 제공 범위로 표시합니다. 유형 분류만으로 난도·정답률이나 실제 출제 가능성을 산출하지 않습니다.</p>';
}
